package zorahm.zochat.badge

import net.kyori.adventure.key.Key
import org.bukkit.configuration.file.YamlConfiguration
import org.bukkit.plugin.Plugin
import java.io.InputStreamReader
import java.io.Reader

/**
 * Which character of the resource pack font is which badge. Generated by tools/prefixgen into the
 * plugin's resources and read from the jar (never copied to the data folder), so the plugin and a
 * pack built from the same commit always agree.
 */
class BadgeTable(val font: Key, private val entries: Map<String, Entry>) {

    class Entry(val labelEn: String, val labelRu: String, private val glyphs: Map<String, Char>) {
        fun glyph(russian: Boolean, icon: Boolean): Char? =
            glyphs[(if (russian) "ru" else "en") + if (icon) "-icon" else ""]
    }

    operator fun get(id: String): Entry? = entries[id.lowercase()]

    companion object {
        @JvmStatic
        fun read(reader: Reader): BadgeTable {
            val yaml = YamlConfiguration.loadConfiguration(reader)
            val section = yaml.getConfigurationSection("badges")
            val entries = section?.getKeys(false)?.associate { id ->
                val badge = section.getConfigurationSection(id)!!
                val glyphs = listOf("en", "en-icon", "ru", "ru-icon")
                    .mapNotNull { variant -> badge.getString(variant)?.let { variant to it.toInt(16).toChar() } }
                    .toMap()
                id.lowercase() to Entry(badge.getString("label-en") ?: id.uppercase(), badge.getString("label-ru") ?: id.uppercase(), glyphs)
            } ?: emptyMap()
            return BadgeTable(Key.key(yaml.getString("font") ?: "zochat:badges"), entries)
        }

        @JvmStatic
        fun load(plugin: Plugin): BadgeTable {
            val resource = plugin.getResource("badges.yml")
            if (resource == null) {
                plugin.logger.warning("badges.yml is missing from the jar - <badge:...> tags will stay as text")
                return BadgeTable(Key.key("zochat:badges"), emptyMap())
            }
            return InputStreamReader(resource, Charsets.UTF_8).use { read(it) }
        }
    }
}
